package main

import (
	"gno.land/r/gov/dao"
	valv3 "gno.land/r/sys/validators/v3"
)

func main(cur realm) {
	r := valv3.NewValidatorProposalRequest(
		cross(cur),
		[]valv3.ValoperChange{
			valv3.NewValoperChange(address("g18x3jntrvu2jmwddsxtqpmzua5cs0fmtf9mda9j"), 1),
			valv3.NewValoperChange(address("g1npaccm9xucl696fns8j7na44fmeucduflh59uu"), 1),
		},
		"Add 2 validator(s) to the valset",
		"Batch-add 2 operator(s) to the active valset with voting power 1.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}

